"""Quarantine confirmation identities whose repositories were previously materialized."""
def audit(split,prior_materializations):
    prior={r["repository"] for material in prior_materializations for r in material["repositories"] if r["status"]=="completed"};quarantined=[r for r in split["confirmation"] if r["full_name"] in prior];clean=[r for r in split["confirmation"] if r["full_name"] not in prior];development_overlap=[r for r in split["development"] if r["full_name"] in prior]
    return {"schema_version":"confirmation-contamination-audit-1","development":split["development"],"revised_confirmation":clean,"quarantined_confirmation":quarantined,"development_prior_overlap":development_overlap,"counts":{"original_confirmation":len(split["confirmation"]),"quarantined_confirmation":len(quarantined),"revised_confirmation":len(clean),"development_prior_overlap":len(development_overlap)},"replacement_performed":False,"revised_confirmation_source_unread":True,"holdout_admission_authorized":False}
